const listProductUUIDs = `-- name: ListProductUUIDs :many
SELECT p.uuid
FROM products p
CROSS JOIN LATERAL (
    SELECT COALESCE(SUM(sl.on_hand), 0) AS on_hand, COALESCE(SUM(sl.reserved), 0) AS reserved
    FROM stock_levels sl
    WHERE sl.organization_id = p.organization_id AND sl.product_id = p.id
      AND ($1::bigint[] IS NULL OR sl.branch_id = ANY($1::bigint[]))
) st
WHERE p.organization_id = $2
  AND p.deleted_at IS NULL
  AND ($3::bigint[] IS NULL OR EXISTS (
        SELECT 1 FROM product_branches pb
        WHERE pb.organization_id = p.organization_id AND pb.product_id = p.id
          AND pb.branch_id = ANY($3::bigint[])))
  AND ($4::boolean IS NULL OR p.is_active = $4)
  AND ($5::boolean IS NULL OR p.show_online = $5)
  AND ($6::text[] IS NULL OR (CASE
        WHEN st.on_hand - st.reserved <= 0 THEN 'out' WHEN st.on_hand - st.reserved <= p.low_stock_threshold THEN 'low' ELSE 'in'
      END) = ANY($6::text[]))
  AND (
    $7::text IS NULL
    OR p.name ILIKE '%' || $7 || '%'
    OR p.sku ILIKE '%' || $7 || '%'
    OR p.barcode = $7
    OR EXISTS (
        SELECT 1 FROM product_variants v
        WHERE v.organization_id = p.organization_id AND v.product_id = p.id AND v.deleted_at IS NULL
          AND (v.name ILIKE '%' || $7 || '%' OR v.sku ILIKE '%' || $7 || '%' OR v.barcode = $7))
  )
ORDER BY p.id ASC
LIMIT $8
`

type ListProductUUIDsParams struct {
	StockBranchIds  []int64     `json:"stock_branch_ids"`
	OrganizationID  int64       `json:"organization_id"`
	FilterBranchIds []int64     `json:"filter_branch_ids"`
	IsActive        pgtype.Bool `json:"is_active"`
	ShowOnline      pgtype.Bool `json:"show_online"`
	StockStatus     []string    `json:"stock_status"`
	Q               pgtype.Text `json:"q"`
	LimitCount      int32       `json:"limit_count"`
}

