const listStockMovements = `-- name: ListStockMovements :many
SELECT
    m.id, m.uuid, m.organization_id, m.branch_id, m.product_id, m.variant_id, m.kind, m.quantity, m.balance_after, m.unit_price, m.unit_cost, m.staff_id, m.counterpart_branch_id, m.transfer_uuid, m.reason, m.note, m.source, m.source_uuid, m.occurred_at, m.created_by, m.created_at,
    p.uuid AS product_uuid, p.name AS product_name, p.sku AS product_sku,
    v.uuid AS variant_uuid, v.name AS variant_name, v.sku AS variant_sku,
    b.uuid AS branch_uuid, b.name AS branch_name,
    cb.uuid AS counterpart_branch_uuid, cb.name AS counterpart_branch_name,
    st.uuid AS staff_uuid, st.name AS staff_name,
    u.uuid AS created_by_uuid, u.name AS created_by_name, u.surname AS created_by_surname,
    EXISTS (
        SELECT 1 FROM stock_movements rm
        WHERE rm.organization_id = m.organization_id AND rm.source = 'sale_return' AND rm.source_uuid = m.uuid
    )::boolean AS returned,
    -- Money of a walk-in sale (TEC-992): collections taken for it and
    -- refunds paid back, reversals netted.
    COALESCE((
        SELECT SUM(CASE WHEN e.direction = 'credit' THEN e.amount ELSE -e.amount END) FROM ledger_entries e
        LEFT JOIN ledger_entries o ON o.organization_id = e.organization_id AND o.id = e.reverses_entry_id
        WHERE e.organization_id = m.organization_id AND e.source_type = 'stock_movement' AND e.source_uuid = m.uuid
          AND COALESCE(o.kind, e.kind) = 'collection'
    ), 0)::numeric AS collected,
    COALESCE((
        SELECT SUM(CASE WHEN e.direction = 'debit' THEN e.amount ELSE -e.amount END) FROM ledger_entries e
        LEFT JOIN ledger_entries o ON o.organization_id = e.organization_id AND o.id = e.reverses_entry_id
        WHERE e.organization_id = m.organization_id AND e.source_type = 'stock_movement' AND e.source_uuid = m.uuid
          AND COALESCE(o.kind, e.kind) = 'refund'
    ), 0)::numeric AS refunded
FROM stock_movements m
JOIN products p ON p.id = m.product_id AND p.organization_id = m.organization_id
JOIN branches b ON b.id = m.branch_id AND b.organization_id = m.organization_id
LEFT JOIN product_variants v ON v.id = m.variant_id AND v.organization_id = m.organization_id
LEFT JOIN branches cb ON cb.id = m.counterpart_branch_id AND cb.organization_id = m.organization_id
LEFT JOIN staff st ON st.id = m.staff_id AND st.organization_id = m.organization_id
LEFT JOIN users u ON u.id = m.created_by
WHERE m.organization_id = $1
  AND ($2::bigint[] IS NULL OR m.branch_id = ANY($2::bigint[]))
  AND ($3::bigint[] IS NULL OR m.branch_id = ANY($3::bigint[]))
  AND ($4::bigint[] IS NULL OR m.product_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR m.staff_id = ANY($5::bigint[]))
  AND ($6::text[] IS NULL OR m.kind = ANY($6::text[]))
  AND ($7::timestamptz IS NULL OR m.occurred_at >= $7::timestamptz)
  AND ($8::timestamptz IS NULL OR m.occurred_at < $8::timestamptz)
  AND (
    $9::text IS NULL
    OR p.name ILIKE '%' || $9 || '%'
    OR p.sku ILIKE '%' || $9 || '%'
    OR v.sku ILIKE '%' || $9 || '%'
    OR m.reason ILIKE '%' || $9 || '%'
    OR m.note ILIKE '%' || $9 || '%'
  )
ORDER BY
  CASE WHEN $10::text = 'occurred_at' AND NOT $11::boolean THEN m.occurred_at END ASC,
  CASE WHEN $10::text = 'quantity' AND NOT $11::boolean THEN m.quantity END ASC,
  CASE WHEN $10::text = 'quantity' AND $11::boolean THEN m.quantity END DESC,
  CASE WHEN $10::text = 'kind' AND NOT $11::boolean THEN m.kind END ASC,
  CASE WHEN $10::text = 'kind' AND $11::boolean THEN m.kind END DESC,
  m.occurred_at DESC, m.id DESC
LIMIT $13 OFFSET $12
`

