const upsertProductBranch = `-- name: UpsertProductBranch :exec
INSERT INTO product_branches (organization_id, product_id, branch_id, price, is_active)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (organization_id, product_id, branch_id) DO UPDATE
SET price = EXCLUDED.price, is_active = EXCLUDED.is_active
`

type UpsertProductBranchParams struct {
	OrganizationID int64          `json:"organization_id"`
	ProductID      int64          `json:"product_id"`
	BranchID       int64          `json:"branch_id"`
	Price          pgtype.Numeric `json:"price"`
	IsActive       bool           `json:"is_active"`
}

func (q *Queries) UpsertProductBranch(ctx context.Context, arg UpsertProductBranchParams) error {
	_, err := q.db.Exec(ctx, upsertProductBranch,
		arg.OrganizationID,
		arg.ProductID,
		arg.BranchID,
		arg.Price,
		arg.IsActive,
	)
	return err
}
